// Minimal Astro Dodge game
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = canvas.clientWidth || 800;
canvas.height = canvas.clientHeight || 600;

// Player ship
const ship = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  r: 12,
  speed: 2,
  fuel: 100,
  dx: 0,
  dy: 0,
};

// Input handling
const keys = {};
window.addEventListener('keydown', e => {keys[e.key] = true;});
window.addEventListener('keyup', e => {keys[e.key] = false;});

function updateShip() {
  let ax = 0, ay = 0;
  if (keys['ArrowLeft'] || keys['a']) ax -= 1;
  if (keys['ArrowRight'] || keys['d']) ax += 1;
  if (keys['ArrowUp'] || keys['w']) ay -= 1;
  if (keys['ArrowDown'] || keys['s']) ay += 1;
  // Normalize diagonal speed
  if (ax || ay) {
    const len = Math.hypot(ax, ay);
    ax /= len; ay /= len;
    ship.dx = ax * ship.speed;
    ship.dy = ay * ship.speed;
    ship.fuel = Math.max(0, ship.fuel - 0.05);
  } else {
    ship.dx = ship.dy = 0;
  }
  ship.x = Math.max(ship.r, Math.min(canvas.width - ship.r, ship.x + ship.dx));
  ship.y = Math.max(ship.r, Math.min(canvas.height - ship.r, ship.y + ship.dy));
}

// Asteroids
const asteroids = [];
function spawnAsteroid() {
  const edge = Math.random() < 0.5 ? 'h' : 'v';
  const r = 10 + Math.random() * 20;
  let x, y, vx, vy;
  if (edge === 'h') {
    x = Math.random() * canvas.width;
    y = Math.random() < 0.5 ? -r : canvas.height + r;
    vy = (Math.random() * 1.5 + 0.5) * (y < 0 ? 1 : -1);
    vx = (Math.random() - 0.5) * 1.5;
  } else {
    x = Math.random() < 0.5 ? -r : canvas.width + r;
    y = Math.random() * canvas.height;
    vx = (Math.random() * 1.5 + 0.5) * (x < 0 ? 1 : -1);
    vy = (Math.random() - 0.5) * 1.5;
  }
  asteroids.push({x, y, vx, vy, r});
}
let asteroidTimer = 0;
function updateAsteroids(dt) {
  asteroidTimer += dt;
  if (asteroidTimer > 1000) { // spawn every second
    spawnAsteroid();
    asteroidTimer = 0;
  }
  for (let i = asteroids.length - 1; i >= 0; i--) {
    const a = asteroids[i];
    a.x += a.vx; a.y += a.vy;
    if (a.x < -a.r || a.x > canvas.width + a.r || a.y < -a.r || a.y > canvas.height + a.r) {
      asteroids.splice(i, 1);
    }
  }
}

function checkCollision() {
  for (const a of asteroids) {
    const d = Math.hypot(ship.x - a.x, ship.y - a.y);
    if (d < ship.r + a.r) return true;
  }
  return false;
}

let lastTime = 0;
let gameOver = false;
function loop(timestamp) {
  const dt = timestamp - lastTime;
  lastTime = timestamp;
  if (!gameOver) {
    updateShip();
    updateAsteroids(dt);
    if (checkCollision() || ship.fuel <= 0) gameOver = true;
  }
  // Render
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  // ship
  ctx.fillStyle = gameOver ? 'gray' : 'cyan';
  ctx.beginPath();
  ctx.arc(ship.x, ship.y, ship.r, 0, Math.PI * 2);
  ctx.fill();
  // asteroids
  ctx.fillStyle = 'brown';
  for (const a of asteroids) {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
    ctx.fill();
  }
  // HUD
  ctx.fillStyle = 'white';
  ctx.font = '16px sans-serif';
  ctx.fillText('Fuel: ' + Math.floor(ship.fuel), 10, 20);
  if (gameOver) {
    ctx.fillStyle = 'red';
    ctx.font = '48px sans-serif';
    ctx.fillText('Game Over', canvas.width / 2 - 120, canvas.height / 2);
  }
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
